import itertools,json
Aopts=['MQR','PQR','KNR','LNP','NPR']
Bopts=['KMQ','KPR','LPR','KNQ','KPQ']
Adays=[{1},{1,7},{3,6},{3},{1,5,7}]
Bdays=[{6,8},{2,7},{3,7,8},{1,2,4},{4}]
As=[a for a in itertools.product(*Aopts) if len(set(a))==5]
Bs=[b for b in itertools.product(*Bopts) if len(set(b))==5]
feasible=[]
for a,b in itertools.product(As,Bs):
    overlap=set(a)&set(b)
    if len(overlap)!=3 or len(overlap&set('KLQ'))!=1: continue
    days={p:set() for p in 'KLMNPQR'}
    for p,d in zip(a,Adays): days[p].update(d)
    for p,d in zip(b,Bdays): days[p].update(d)
    score=sum(len(d)>=3 for d in days.values())
    feasible.append((score,a,b))
lo=min(feasible,key=lambda x:x[0]); hi=max(feasible,key=lambda x:x[0])
def witness(x): return {'A':''.join(x[1]),'B':''.join(x[2])}
result={'feasible_linkages':len(feasible),'bounds':[lo[0],hi[0]],'low_witness':witness(lo),'high_witness':witness(hi),'decision':'confirmed' if lo[0]>=5 else 'excluded' if hi[0]<5 else 'undetermined'}
payload=json.dumps(result)
r=json.loads(payload)
# Independently validate serialized witnesses using day-by-day credits.
for key,target in [('low_witness',r['bounds'][0]),('high_witness',r['bounds'][1])]:
    w=r[key]
    for namespace,opts in [('A',Aopts),('B',Bopts)]:
        assert len(w[namespace])==5 and len(set(w[namespace]))==5
        assert all(p in opt for p,opt in zip(w[namespace],opts))
    both=set(w['A']).intersection(w['B'])
    assert len(both)==3 and len(both.intersection('KLQ'))==1
    counts={p:0 for p in 'KLMNPQR'}
    for day in range(1,9):
        present={w[ns][i] for ns,ds in [('A',Adays),('B',Bdays)] for i in range(5) if day in ds[i]}
        for p in present: counts[p]+=1
    assert sum(c>=3 for c in counts.values())==target
print(payload)
print('Verified witness constraints and attendance counts; candidate export assignments:',len(As),len(Bs))

